describe('Change Password from Profile Settings', () => {
  beforeEach(() => {
    cy.visit('/profile');
    cy.intercept('GET', '/api/user/profile').as('getUserProfile');
    cy.intercept('POST', '/api/user/change-password').as('changePassword');
    cy.wait('@getUserProfile');
  });

  it('should successfully change password with valid credentials', () => {
    // Navigate to password change section
    cy.get('[data-testid="profile-nav-settings"]').click();
    cy.get('[data-testid="settings-menu-item-security"]').click();

    // Verify password change form is visible
    cy.get('[data-testid="password-change-form"]').should('be.visible');
    cy.get('[data-testid="current-password-input"]').should('be.visible');
    cy.get('[data-testid="new-password-input"]').should('be.visible');
    cy.get('[data-testid="confirm-password-input"]').should('be.visible');
    cy.get('[data-testid="change-password-button"]').should('be.visible');

    // Fill in valid credentials
    cy.get('[data-testid="current-password-input"]').type('OldPassword123');
    cy.get('[data-testid="new-password-input"]').type('NewSecurePassword123!');
    cy.get('[data-testid="confirm-password-input"]').type('NewSecurePassword123!');

    // Submit the form
    cy.get('[data-testid="change-password-button"]').click();

    // Wait for API call and verify success message
    cy.wait('@changePassword');
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Password updated successfully');

    // Verify form is cleared or redirected
    cy.get('[data-testid="password-change-form"]').should('not.exist');
    cy.get('[data-testid="profile-nav-settings"]').should('be.visible');
  });

  it('should display error message when new password does not match confirmation', () => {
    // Navigate to password change section
    cy.get('[data-testid="profile-nav-settings"]').click();
    cy.get('[data-testid="settings-menu-item-security"]').click();

    // Fill in current password
    cy.get('[data-testid="current-password-input"]').type('OldPassword123');

    // Fill in mismatched new password
    cy.get('[data-testid="new-password-input"]').type('NewPassword123!');
    cy.get('[data-testid="confirm-password-input"]').type('DifferentPassword123!');

    // Attempt to submit the form
    cy.get('[data-testid="change-password-button"]').click();

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Passwords do not match');

    // Verify success message does not appear
    cy.get('[data-testid="success-message"]').should('not.exist');

    // Verify form is still visible and fields retain values
    cy.get('[data-testid="password-change-form"]').should('be.visible');
    cy.get('[data-testid="new-password-input"]').should('have.value', 'NewPassword123!');
  });
});
